import sys

MOD = 998244353

def mat_mul(a, b):
    n = len(a)
    c = [[0] * n for _ in range(n)]
    for i in range(n):
        ci = c[i]
        for k in range(n):
            aik = a[i][k]
            if aik:
                bk = b[k]
                for j in range(n):
                    ci[j] = (ci[j] + aik * bk[j]) % MOD
    return c

def mat_pow(a, e):
    n = len(a)
    r = [[0] * n for _ in range(n)]
    for i in range(n):
        r[i][i] = 1
    while e:
        if e & 1:
            r = mat_mul(r, a)
        a = mat_mul(a, a)
        e >>= 1
    return r

def main():
    n = int(sys.stdin.readline())

    A = [
        [1, 1, 0],
        [0, 1, 1],
        [0, 0, 1]
    ]
    B = [
        [0, 0, 0],
        [0, 0, 0],
        [2, 1, 0]
    ]

    size = 12
    T = [[0] * size for _ in range(size)]

    def add_transition(old_mask, new_mask, x):
        for i in range(3):
            row = T[old_mask * 3 + i]
            for j in range(3):
                row[new_mask * 3 + j] = (
                    row[new_mask * 3 + j] + x[i][j]
                ) % MOD

    for mask in range(4):
        if mask & 1:
            add_transition(mask, mask >> 1, A)
        else:
            add_transition(mask, mask >> 1, B)

            if not (mask & 2):
                add_transition(mask, 1, A)

            add_transition(mask, (mask >> 1) | 2, A)

    P = [[0] * 4 for _ in range(4)]
    for mask in range(4):
        if mask & 1:
            P[mask][mask >> 1] += 1
        else:
            if not (mask & 2):
                P[mask][1] += 1
            P[mask][(mask >> 1) | 2] += 1

    TN = mat_pow(T, n)
    PN = mat_pow(P, n)

    total = sum(TN[i][i] for i in range(size)) % MOD
    no_diameter = sum(PN[i][i] for i in range(4)) % MOD

    print((total - 3 * no_diameter) % MOD)

if __name__ == "__main__":
    main()

