                (b[i] if i < len(b) else 0)) % MOD
    return trim(c)

def sub(a, b):
    n = max(len(a), len(b))
    c = [0] * n
    for i in range(n):
        c[i] = ((a[i] if i < len(a) else 0) -
                (b[i] if i < len(b) else 0)) % MOD
    return trim(c)

def mul(a, b):
    c = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                if y:
                    c[i + j] = (c[i + j] + x * y) % MOD
    return trim(c)

def shift(a, k):
    return [0] * k + a

def log_derivative_coeff(poly, n):
    d = len(poly) - 1
    res = [0] * (n + 1)
    for i in range(1, n + 1):
        value = i * (poly[i] if i <= d else 0)
        upper = min(d, i - 1)
        for j in range(1, upper + 1):
            value -= res[i - j] * poly[j]
        res[i] = value % MOD
    return res[n]

