def mul(a, b):
    c = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                c[i + j] = (c[i + j] + x * y) % MOD
    return trim(c)

def scale(a, k):
    return trim([(x * k) % MOD for x in a])

def derivative(a):
    if len(a) <= 1:
        return [0]
    return trim([(i * a[i]) % MOD for i in range(1, len(a))])

def shift(a, k):
    if a == [0]:
        return [0]
    return [0] * k + a

def apply_operator(num, den, c):
    left = mul(derivative(num), den)
    right = mul(num, derivative(den))
    numerator = shift(sub(left, right), 1)
    if c:
        numerator = add(numerator, scale(mul(num, den), c))
    denominator = mul(den, den)
    return numerator, denominator

def build_entry(c, shift_amount):
    num = [1]
    den = [1, 0, MOD - 1, 0, MOD - 1]
    num, den = apply_operator(num, den, c)
    num, den = apply_operator(num, den, c)
    return shift(num, shift_amount), den

def main():
    n = int(sys.stdin.readline())

    n00, q = build_entry(0, 1)
    n01, _ = build_entry(1, 2)
    n11, _ = build_entry(2, 3)

    p = sub(mul(sub(q, n00), sub(q, n11)), mul(n01, n01))

    numerator = sub(
        scale(mul(derivative(q), p), 2),
        mul(derivative(p), q)
    )
    denominator = mul(q, p)

    target = n - 1
    coefficients = [0] * (target + 1)
    inv_const = pow(denominator[0], MOD - 2, MOD)

    for i in range(target + 1):
        value = numerator[i] if i < len(numerator) else 0
        limit = min(i, len(denominator) - 1)
        for j in range(1, limit + 1):
            value -= denominator[j] * coefficients[i - j]
        coefficients[i] = value % MOD * inv_const % MOD

    print(coefficients[target])

